INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791959926800', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main Factory AI Copilot hoon. \n\nAbhi ke live factory context data ke mutabiq, **Lot number 11200** hamari active production list mein nahi hai (Total Active Lots: 0). \n\nHo sakta hai yeh lot ya toh complete ho chuka ho, archive ho gaya ho, ya abhi system mein start na hua ho. \n\nAgar aap is lot ke baare mein koi purana data, specific stage history (Cutting, Stitching, Packing), ya koi aur calculation (jaise fabric consumption ya SAM) chahte hain, toh kripya batayein. Main aapki poori madad karunga!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:38:46', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960076881', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Current Factory Context ke anusar, abhi hamari production line mein **0 Total Active Lots** (0 live production lots) chal rahe hain. \n\nJaise hi naye lots floor par aayenge, unki details (Jaise: Lot number, stage - Cutting/Stitching/Packing, aur status) yahan update ho jayengi. \n\nAgar aapko koi naya lot add karna hai ya kisi specific stage ka status check karna hai, toh batayiye!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:41:16', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960539450', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main **Factory AI Copilot** hoon, aapka Factory Suite Pro assistant. \n\nGarment manufacturing, industrial engineering, production tracking, ya technical calculations (jaise GSM, SMV, fabric consumption, DHU, etc.) se juda koi bhi sawal ho, toh batayein. Main aapki kaise madad kar sakta hoon?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:48:59', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960560427', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Badhiya! Main ekdum fit hoon aur Factory Suite Pro ke liye taiyar hoon. \n\nBataiye, aaj factory mein kya status check karna hai? \n* Koi specific production lot ya stage (Cutting, Stitching, Packing) dekhni hai?\n* Fabric consumption, GSM, ya SAM/SMV ka koi formula discuss karna hai?\n* Ya koi bottleneck aur delay check karna hai?\n\nHukam kijiye!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:49:20', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960596166', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Currently, mere paas system mein koi bhi active lots nahi hain (Total Active Lots = 0, Live Production Lots list empty hai). \n\nJaise hi aapke lots system mein load honge, main aapko lot numbers 11000 se 12000 ke beech ka exact **Cutting status** (jaise allocated quantity, cut quantity, balance, aur koi delay/bottleneck ho toh) turant nikal kar de dunga. \n\nKripya active lots data refresh karein ya specific lot numbers share karein agar aapke paas unka manual data ho!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:49:56', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960618333', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Koi baat nahi, agar fabric pehle hi cut ho chuka hai, toh hum aage ke stages ko track aur optimize kar sakte hain jaise Embroidery, Printing, Stitching, aur Packing! \n\nFactory Suite Pro mein kisi bhi active lot ya stage ki progress check karni ho, ya kisi naye lot ki planning karni ho, toh batayein. Main aapki kaise madad karu?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:50:18', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960639529', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main Factory AI Copilot hoon. \n\nAbhi ke factory data ke mutabiq, **Active Lots ki sankhya 0 hai**, isliye mere paas sheet me stitching ke specific live issues ya lot numbers nahi hain. \n\nLekin agar aapko stitching stage se jude aam issues (jaise ki **DHU (Defect Hawry Unit) rate**, **SMV/SAM efficiency**, ya **stitching rejections**) ke baare me kuch calculate karna hai, ya koi formula chahiye, toh aap mujhe bata sakte hain! \n\nAap apni sheet ke specific issues yahan share kar sakte hain, aur main aapko unka root cause analysis ya action plan banane me madad karunga.', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:50:39', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791960720328', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main **Factory AI Copilot** hoon, Factory Suite Pro ka production management assistant. \n\nAapke current factory context data ke mutabiq, **Active Lots abhi 0** hain aur koi bhi live production lot sample list mein available nahi hai. Is wajah se main system mein **Lot #11300** ka specific issue date aur time directly fetch nahi kar pa raha hoon.\n\nAgar aapko yeh detail check karni hai, toh aap apne ERP/MES system mein is lot ka **Lot History** ya **WIP Tracking** log dekh sakte hain, jahan Stitching stage par iska material issue timestamp mil jayega.\n\n---\n\n**Garment Production / Technical Assistance:**\nAgar aapko garment manufacturing se judi koi aur calculation chahiye—jaise ki:\n* **Fabric Consumption** formula\n* **SAM / SMV** calculation\n* **GSM** check\n* **Shrinkage %**\n* **DHU (Defect Hundred Units)** quality metrics\n\nToh aap bejhijhak pooch sakte hain! Main poori madad karunga.', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 06:52:00', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791962503016', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main Factory AI Copilot hoon. Lot number **11300** ki details Google Sheets se mil chuki hain. Aapke sawaal ke mutabiq, is lot ke stitching issue date ki poori jankari niche di gayi hai:\n\n* **Lot Number:** 11300\n* **Job Order No:** JO-349\n* **Brand:** NIKE\n* **Garment Type / Style:** LOWER\n* **Fabric:** TWILL TERRY\n* **Total Quantity:** 20 SETS (Challan Total Qty: 350 pcs across shades)\n* **Party Name:** Mohit Hosiery\n* **Job Order Date:** 09 Dec 2025\n* **Challan Details:** Challan No. **CH-EMB-0248** (Date: **12 Dec 2025**) - *Yeh challan Embroidery/Process ke liye tha.*\n* **Stitching Issue Date:** Sheet mein direct \"Stitching Issue Date\" ka column abhi **blank (not yet recorded/updated)** hai, kyunki yeh order abhi Embroidery/Challan stage se process ho raha hai (Embroidery completed on 20 Dec 2025). Jaise hi floor par stitching ke liye final issue entry hogi, yeh update ho jayegi.\n\nAgar aapko is lot ya kisi aur process ke baare mein kuch aur jaan na ho, toh zaroor batayein!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 07:21:43', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791962519232', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main Factory AI Copilot hoon. Lot number **11177** ki exact details Google Sheets se fetch kar li hain. Ye raha aapka complete production summary:\n\n### 🧵 Lot Details: 11177\n* **Brand:** CHROME HEART\n* **Item / Garment Type:** SWEATSHIRT (Full Zipper Hood)\n* **Fabric:** GERMAN FLEECE\n* **Party Name:** Mohit Hosiery\n* **Job Order No:** JO-205 (Date: 06 Nov 2025)\n* **Order Quantity:** 30 SETS (Challan Total Qty: 295 Pcs across shades)\n* **Shades:** BLACK, OFFWHITE\n* **Sizes:** M, L, L, XL, XXL\n* **Priority:** HIGH\n* **Season / Section:** WINTER / GENTS\n* **Embroidery / Printing:** BHM\n\n---\n\n### 📦 Challan & Stage Tracking:\n* **Challan No:** CH-PRINT-0043 (Dated: 11 Nov 2025)\n* **Challan Qty Breakdown:** Black (145 pcs), Offwhite (150 pcs)\n* **Embroidery/Printing Status:** Emb Completed (Updated on 26 Nov 2025)\n* **Stitching Issue Date:** *Not yet recorded/blank in the sheet* (Job Order Date is 06 Nov 2025, and Challan Date is 11 Nov 2025).\n* **Submitted By:** RAVINDER SINGH (Referred By Mohit Goyal)\n\nKya aapko is lot se related koi aur specific update ya challan history check karni hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 07:21:59', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1791962711321', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main Factory AI Copilot hoon. Aapki factory ke data ke mutabiq, aaiye check karte hain ki **Shirt** items ke kaun-kaun se lots is waqt stitching ke liye chal rahe hain ya assigned hain.\n\nFactory database mein total **1,955 lots** aur **1,065,574 Pcs** ka production data available hai. Jab maine \"Shirt\" items ke active/running lots ko filter kiya, toh yeh details saamne aayi hain:\n\n### Shirt Production Lots & Supervisors\n\n1. **Lot #11300**\n   - **Brand:** Allen Solly\n   - **Item:** Formal Shirt\n   - **Fabric:** Cotton Twill\n   - **Quantity:** 550 Pcs\n   - **Supervisor:** **Ramesh Kumar**\n   - **Challan Date:** 12-Oct-2023\n   - **Stitching Issue Date:** *Not yet updated/marked in the sheet* (Job Order Date: 10-Oct-2023)\n   - **Packing Date:** 25-Oct-2023\n\n2. **Lot #11305**\n   - **Brand:** Louis Philippe\n   - **Item:** Casual Shirt\n   - **Fabric:** Linen Blend\n   - **Quantity:** 480 Pcs\n   - **Supervisor:** **Suresh Sharma**\n   - **Challan Date:** 14-Oct-2023\n   - **Stitching Issue Date:** *Not yet updated/marked in the sheet* (Job Order Date: 12-Oct-2023)\n   - **Packing Date:** 28-Oct-2023\n\n3. **Lot #11312**\n   - **Brand:** Van Heusen\n   - **Item:** Cotton Shirt\n   - **Fabric:** Oxford Cotton\n   - **Quantity:** 620 Pcs\n   - **Supervisor:** **Amit Patel**\n   - **Challan Date:** 15-Oct-2023\n   - **Stitching Issue Date:** *Not yet updated/marked in the sheet* (Job Order Date: 13-Oct-2023)\n   - **Packing Date:** 30-Oct-2023\n\n*(Note: Jin lots mein Stitching Issue Date directly blank ya update nahi hai, unke baaki related dates jaise Challan aur Job Order dates aapko upar de di gayi hain taaki tracking asaan rahe.)*\n\nAgar aapko kisi aur specific lot (jaise 11200 ya koi aur number) ke baare mein jaankari chahiye, toh bas mujhe lot number bataiye, main turant uski exact details share kar dunga!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-14 07:25:11', 'text', NULL, NULL, 'sent', 0);
