INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064473833', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Factory Suite Pro mein aapka swagat hai. \n\nMaine aapka pichla sawaal dekha: **\"TOTAL KITNE LOT CUTTING HUA HAU\"** (Total kitne lots ki cutting ho chuki hai?).\n\nMere current active factory context ke mutabiq, abhi system mein koi bhi active lot registered nahi hai (Total Active Lots: 0). Jaise hi cutting department se naye lots issue aur cut hokar update honge, main aapko turant exact count aur unki details bata dunga.\n\nKya aapko kisi specific Job Order ya lot ke baare mein janna hai? Ya fir aap cutting data ko sheet se refresh karna chahte hain?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:41:13', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064487890', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello ji! Factory Suite Pro mein aapka swagat hai. \n\nBataiye, aaj factory floor par main aapki kya madad kar sakta hoon? Koi naya lot status check karna hai, cutting/stitching data dekhna hai, ya kisi garment technical query (jaise GSM, consumption, ya SAM) par baat karni hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:41:27', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064492127', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Main ekdum theek hoon, ji! Aap bataiye, aap kaise hain? \n\nFactory floor par sab theek-thaak chal raha hai? Bataiye, aaj production, cutting, ya kisi aur process mein main aapki kya madad kar sakta hoon?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:41:32', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064501134', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Bahut badhiya! Sun kar khushi hui. \n\nBataiye, aaj factory mein kya chal raha hai? Koi production report dekhni hai, kisi style ka fabric consumption nikalna hai, ya kisi stage (cutting, stitching, packing) ka status check karna hai? Main poori tarah taiyar hoon!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:41:41', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064514029', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Bas, aapke factory floor par nazar banaye hue hoon! \n\nFilhal mere paas system mein koi active lot nahi chal raha hai, lekin main poori tarah ready hoon. Aap bataiye, kya check karna hai? \n\n1. **New Lot create karna hai** ya kisi style ki **fabric consumption / SAM** nikalni hai?\n2. Kisi purane order ka status dekhna hai?\n3. Cutting, Stitching, ya Quality (DHU) se juda koi data discuss karna hai?\n\nHukam kijiye, kya dekhna chahenge aap?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:41:54', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064560942', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Haha, bas aise hi aapke saath ready baitha hoon! 😊\n\nBataiye, aaj factory mein koi naya order ya style discuss karna hai kya? \n\nJaise ki:\n* Kisi naye style ka **Fabric Consumption** ya **SAM (Standard Allowed Minute)** nikalna ho?\n* **GSM** ya **Shrinkage %** ka formula discuss karna ho?\n* Ya koi naya production lot plan karna ho?\n\nBoliye, kya help karun?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:42:40', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064566542', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Haan ji, boliye! Kya sawaal hai aapka? \n\nChahe factory production se juda ho, fabric consumption ya GSM ka formula ho, ya garment manufacturing ka koi bhi technical sawaal ho—mai bilkul tayar hoon jawab dene ke liye. Poochiye!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:42:46', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064585154', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Main **Factory Suite Pro** ka **Factory AI Copilot** hoon! Garment manufacturing aur factory operations ko smooth chalane ke liye main aapki in sabhi cheezon mein help kar sakta hoon:\n\n1. **Production Tracking & Floor Control:**\n   * Live lots ka status check karna (Cutting se lekar Packing tak ke sabhi stages par).\n   * Bottlenecks aur delays (Jahan kaam atka ho) ko identify karna.\n   * Efficiency aur Output (KPIs) par nazar rakhna.\n\n2. **Technical Calculations (Merchandising & Industrial Engineering):**\n   * **Fabric Consumption:** Kisi bhi style (Shirt, T-Shirt, Trouser, Kurti, etc.) ka marker/consumption nikalna.\n   * **SAM / SMV (Standard Allowed Minute):** Operations ki sewing time calculation aur line balancing mein madad.\n   * **GSM & Shrinkage:** Fabric weight aur wash shrinkage % ke formulas aur calculations.\n\n3. **Quality Management:**\n   * DHU (Defect Hundred Units) calculate karna aur quality issues par suggestions dena.\n\n4. **Planning & Execution:**\n   * Naye production lots plan karne mein guidance.\n\nBoliye Boss, aaj factory floor par kya task perform karna hai? Koi naya style discuss karna hai ya kisi order ka status dekhna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:43:05', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064609291', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Bilkul boss! Chaliye aapke factory floor ke current status ko check karte hain. \n\nAbhi ke data ke mutabiq:\n* **Total Active Lots:** 0 (Filhal koi active production lot system mein nahi chal raha hai).\n* **Live Production Lots (Sample):** Empty.\n\nJab factory mein active lots hi nahi hain ya production data live feed nahi ho raha hai, toh hume koi **active bottlenecks (jahan kaam atka ho)** nahi dikh rahe hain.\n\n**Kya aap chahte hain ki main:**\n1. Koi naya production lot add karun ya simulate karun?\n2. Kisi specific style/stage (Cutting, Stitching, Packing) ki capacity ya potential bottlenecks ke baare mein baat karun?\n\nBoliye, kya kiya jaye?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:43:29', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064632166', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Mujhe **Factory Suite Pro** ke expert AI ke roop mein train kiya gaya hai, jo specifically **garment manufacturing, industrial engineering (IE), aur factory floor operations** ke liye design kiya gaya hai. \n\nMeri training data aur capabilities mein yeh sab shamil hai:\n\n1. **Garment Industry Domain Knowledge:** \n   * Cutting, Stitching (Sewing), Finishing, aur Packing processes ki deep understanding.\n   * Technical formulas jaise Fabric Consumption, SAM/SMV (Standard Allowed Minute), GSM, aur DHU (Defect Hundred Units) calculations.\n\n2. **Real-Time Data Integration:** \n   * Factory ke live production lots, stages, aur KPIs ko read karke bottlenecks aur delays turant spot karne ki capability.\n\n3. **Language & Communication (Hinglish/Hindi/English):** \n   * Factory floor par supervisors, managers, aur owners jis bhasha mein baat karte hain (Hinglish aur aam bolchal ki bhasha), usme aasani se baat karne ke liye trained hoon taaki instructions clear rahein.\n\nIn short, mujhe ek **Virtual Production Manager** ki tarah banaya gaya hai jo aapki factory ki efficiency aur productivity badhane mein help kare. \n\nBoliye Boss, aaj factory floor par koi calculation karni hai ya kisi naye order ki planning karni hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:43:52', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064650492', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, mere current system data aur context ke mutabiq aapki company ka specific naam yahan register ya update nahi kiya gaya hai. Main **Factory Suite Pro** ke AI Copilot ke taur par aapke factory operations, production tracking, aur calculations ko manage karne ke liye yahan hoon. \n\nAgar aap chahen toh main system mein aapki company ka naam set kar sakta hoon, ya aap mujhe bata sakte hain ki aapki company ka kya naam hai! \n\nBoliye, aage kya help karun? Koi naya order plan karna hai ya koi calculation karni hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:44:10', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064688377', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Mujhe train karne ke liye aur ek expert **Factory AI Copilot** banane ke liye mukhyata in cheezon ka use kiya gaya hai:\n\n1. **Garment & Textile Domain Data:** \n   * Cutting, Stitching, Finishing aur Packing ke industrial standards.\n   * Industrial Engineering (IE) ke formulas jaise SAM/SMV (Standard Allowed Minute), Fabric Consumption, aur Quality metrics (DHU - Defect Hundred Units).\n\n2. **Large Language Models (LLMs):** \n   * Advanced AI technology jo natural language (jaise Hinglish, Hindi, aur English) ko samajhne aur garment industry ki bhasha mein exact jawab dene mein madad karti hai.\n\n3. **Factory Suite Pro Framework:** \n   * Yeh ek specialized production management system hai, jisse mujhe factory floor ke live data (jaise active lots, stages, bottlenecks aur KPIs) ke sath integrate kiya gaya hai taaki main real-time insights de sakun.\n\nSimple shabdon mein kahein toh—**Garment manufacturing ka technical knowledge + Factory management ka data + Advanced AI**—in sabko mila kar mujhe banaya gaya hai! \n\nBoliye Boss, factory floor se judi koi calculation ya planning karni hai aaj?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:44:48', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792064722837', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hola, Boss! 👋 \n\nBoliye, aaj factory floor par kya chal raha hai? Koi naya order plan karna hai, ya kisi garment ki consumption ya SAM calculation karni hai? Main taiyar hoon!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:45:22', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065002099', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, Factory Suite Pro mein **Bottleneck Report** ko garment production floor ki real-time performance aur constraints ke basis par design kiya gaya hai. Yeh report mainly in 4 parameters par kaam karti hai:\n\n1. **WIP (Work in Progress) Accumulation:** \n   * Kis stage (jaise Stitching, Finishing ya Quality Check) par sabse zyada bundles ya pieces accumulate (jama) ho rahe hain, jisse aage ki line slow ho rahi ho.\n\n2. **Stage-wise Target vs. Actual Output:** \n   * Planned hourly output aur live actual output ka comparison. Agar koi stage apne target se consistently peeche hai, toh wo bottleneck mark hoti hai.\n\n3. **Machine & Manpower Utilization:** \n   * Kaunse operations par operators ki kami hai ya machines under-utilized/over-loaded hain (jaise agar special machines ki shortage hai).\n\n4. **Line Balancing & SMV/SAM Delays:** \n   * Agar kisi operation ka Standard Allowed Minute (SAM) high hai aur operator ki efficiency kam hai, toh wahan balancing disrupt ho jati hai, jisse queue banne lagti hai.\n\nSimple words mein kahein toh—**\"Kahan par maal atak raha hai aur kiske karan target miss ho raha hai\"**—yeh report yeh exact identify karke deti hai taaki aap time par corrective action le sakein.\n\nBoliye Boss, kya current active lots ke liye koi bottleneck analysis run karni hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:50:02', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065016939', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', '**PulseBot AI Capabilities Cheatsheet:**\n\nAap mujhe inme se kisi bhi format mein questions pooch sakte hain:\n\n1. **✂️ Cutting & Lot Inquiries:**\n   - *\"Is Lot 61008 cut or pending?\"*\n   - *\"Details of Lot 11028\"*\n   - *\"Fabric of Lot 11028\"*\n   - *\"Who is the party for Lot 61001?\"*\n\n2. **🏢 Parties & Buyers:**\n   - *\"How many lots of SS?\"* (Accurate 331 count + cut breakdown)\n   - *\"Show pending lots for SS\"*\n   - *\"Mohit Hosiery total lots\"*\n   - *\"List all parties\"*\n   - *\"Which party has the most orders?\"*\n\n3. **📊 Factory Production Overview:**\n   - *\"How many lots are cut in total?\"*\n   - *\"Overall cutting status\"*\n   - *\"Kaun se lot pending hain?\"*\n\n4. **👕 Garments & Fabrics:**\n   - *\"How many Lower lots do we have?\"*\n   - *\"List all garment categories\"*\n   - *\"Lots using fabric German Fleece\"*\n   - *\"List top fabrics\"*\n\n5. **🪡 Embroidery & Vendors:**\n   - *\"BHM embroidery lots\"*\n   - *\"Direct stitching lots\"*\n\n6. **👥 Supervisors & Team:**\n   - *\"Who is the fabric supervisor?\"*\n   - *\"Who is packing supervisor?\"*\n   - *\"List team members\"*\n   - *\"What tasks are overdue?\"*\n\n7. **📄 PDF Reports:**\n   - *\"Generate PDF for SS\"* (Generates full 331-lot PDF report)\n   - *\"Download cutting slip for Lot 61008\"*', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:50:16', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065035208', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, **SAM** ka matlab hota hai **Standard Allowed Minute** (kai jagah ise **SMV** yaani *Standard Minute Value* bhi kehte hain). \n\nYeh garment industry ka sabse important metric hai jo yeh batata hai ki **ek garment (ya ek specific operation) ko banane mein kitna standard time lagna chahiye.**\n\nChaliye isko bilkul simple steps mein samajhte hain:\n\n---\n\n### 1. SAM mein kya-kya include hota hai?\nSAM sirf akele sewing ka time nahi hai. Isme 3 cheezein milti hain:\n* **Basic Operation Time:** Machine par actual stitching ya kaam karne ka time.\n* **Allowance (Relaxation Allowance):** Operator ki fatigue (thakawat), personal needs, aur machine ki choti-moti delays (jaise thread tootna) ke liye extra time percentage (aamtaur par 10% to 15% add hota hai).\n* **Bundle Handling Time:** Maal uthana, rakhna, aur bundle kholna/baandhna.\n\n---\n\n### 2. SAM calculate kaise hota hai? (Formula)\nIndustry mein SAM nikalne ka standard tareeqa yeh hai:\n\n$$\\text{SAM} = \\text{Normal Time} \\times \\left(1 + \\frac{\\text{Allowance \\%}}{100}\\right)$$\n\nJahan **Normal Time** nikalne ke liye yeh formula hota hai:\n$$\\text{Normal Time} = \\text{Observed Time (Stopwatch se liya gaya time)} \\times \\text{Rating Factor (Operator ki speed ka scale)}$$\n\n*Example:* Agar ek operation ka average time 1 minute aaya aur operator ki speed (Rating) 100% thi, aur factory ka allowance 15% hai, toh:\n$$\\text{SAM} = 1.0 \\times 1.15 = 1.15 \\text{ Minutes}$$\n\n---\n\n### 3. Factory mein SAM kyun zaroori hai? (Why it matters)\nAgar aapko apne garment ka SAM pata hai, toh aap yeh sab asani se kar sakte hain:\n1. **Line Balancing:** Kis operation par kitne operators lagane hain taaki line block na ho (bottleneck na bane).\n2. **Target Setting:** Ek din mein ek line kitne pieces banayegi, uska exact calculation.\n   $$\\text{Target per hour} = \\frac{60 \\text{ minutes} \\times \\text{Number of Operators}}{\\text{Total SAM of the Garment}}$$\n3. **Costing & Pricing:** Buyer ko rate dene ke liye labor cost calculate karna.\n4. **Efficiency Tracking:** Operator ki actual performance vs. Standard performance measure karna.\n\nBoliye Boss, kya kisi specific garment (jaise T-shirt ya Lower) ka SAM calculate karne ka example dekhna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:50:35', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065159702', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', '**Factory Suite Pro mein T-SHIRT category ke total 486 lots hain.**\n\n* **Total Lots:** **486 Lots**\n* **[✓] Cut Complete:** **409 Lots**\n* **[!] Cutting Pending:** **77 Lots**\n* **Sample Lot Numbers:** 11143, 11144, 11145, 11168, 11171, 11181, 11195, 11206, 11207, 11208, 11210, 11211...\n\nAgar aapko is category ka full data ya PDF chahiye, toh zaroor batayein!', NULL, NULL, '{\"type\":\"party\",\"title\":\"T-SHIRT Category - Production & Cutting Report\",\"filename\":\"T-SHIRT_Category_Report.pdf\",\"partyName\":\"T-SHIRT Category\",\"downloadUrl\":\"http://localhost:5000/api/chat/pdf/party/T-SHIRT\"}', NULL, NULL, 1, '2026-10-15 11:52:39', 'text', NULL, NULL, 'sent', 0);
