INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065197115', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, **SAM (Standard Allowed Minute)** garment industry ka woh core metric hai jo yeh batata hai ki **ek specific garment ya operation ko complete karne mein kitna standard time lagna chahiye**. \n\nIsko bilkul simple aur short mein samajhte hain:\n\n---\n\n### 1. Formula & Calculation Steps:\n$$\\text{SAM} = \\text{Normal Time} \\times \\left(1 + \\frac{\\text{Allowance \\%}}{100}\\right)$$\n\n* **Step 1: Observed Time (OT)** — Stopwatch se operator ka liya gaya actual time.\n* **Step 2: Rating Factor (RF)** — Operator ki speed ki performance (e.g., standard speed = 100% ya 1.0).\n  $$\\text{Normal Time} = \\text{OT} \\times \\text{RF}$$\n* **Step 3: Allowance** — Thakawat (fatigue), personal needs aur machine delays ke liye extra time add karna (aamtaur par 10% se 15%).\n\n---\n\n### 2. Industry mein SAM kyun zaroori hai?\n1. **Line Balancing:** Kis operation par kitne operators lagane hain, yeh decide karne ke liye.\n2. **Production Target:** Ek din mein line kitne pieces banayegi, uska exact target nikalne ke liye.\n3. **Costing & Efficiency:** Labor cost calculate karne aur operators ki daily efficiency track karne ke liye.\n\nBoliye Boss, kya T-shirt ya kisi aur specific garment ka operation-wise SAM breakdown dekhna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:53:17', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065223679', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Haan bilkul Boss! Yeh lijiye Python mein \"Hello World\" print karne ka ekdum simple code:\n\n```python\nprint(\"Hello World\")\n```\n\nAap ise kisi bhi Python environment (jaise VS Code, Jupyter, ya terminal) mein run kar sakte hain. \n\nGarment manufacturing, Python automation, ya Factory Suite Pro ke kisi aur data/logic ke baare mein kuch aur poochna ho toh zaroor batayein!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:53:43', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065251197', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, garment aur manufacturing industry mein **OCR** ka matlab **Optical Character Recognition** hota hai. \n\nYeh ek aisi technology hai jo **images ya scanned documents ke text ko machine-readable digital text mein convert karti hai**.\n\nIsko bilkul simple aur short mein samajhte hain:\n\n---\n\n### 1. Garment Industry mein OCR kahan use hota hai?\n1. **Bundle Tag / Barcode Scanning:** Cutting ya stitching floor par bundles par lage tags ko fast read karne ke liye.\n2. **Quality Audit Sheets:** Inspection ke dauran handwritten defect reports ya audit logs ko digital data mein convert karne ke liye.\n3. **Fabric Roll Inward:** Supplier ke invoice ya roll number ke labels ko automatically system mein scan karne ke liye taaki manual typing ki galti na ho.\n4. **Shipping & Packing Labels:** Cartons par lage address aur SKU details ko instantly read karke ERP/WMS (Warehouse Management System) mein update karne ke liye.\n\n---\n\n### 2. Yeh kaam kaise karta hai?\n* **Step 1 (Image Capture):** Scanner ya camera se document/tag ki photo li jaati hai.\n* **Step 2 (Processing):** Software image ko analyze karta hai, letters aur numbers ko recognize karta hai.\n* **Step 3 (Output):** Text format mein data export kar deta hai jo Factory Suite Pro jaise software mein direct save ho jata hai.\n\nBoliye Boss, kya factory automation ya Factory Suite Pro ke kisi data flow mein OCR integration ke baare mein janna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:54:11', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065325207', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, garment manufacturing aur supply chain industry mein **SSG Mode** ka alag-alag context ho sakta hai, lekin aamtaur par iska matlab **\"Single-Size-Group\" Mode** ya kuch advanced systems mein **\"Smart Style Group\" Mode** hota hai.\n\nIsko apparel industry ke perspective se simple terms mein samajhte hain:\n\n---\n\n### 1. Single-Size-Group (SSG) Mode\n* **Kahan use hota hai:** Cutting room, sorting, aur bundling area mein.\n* **Matlab:** Jab ek hi bundle ya sorting process mein sirf **ek hi specific size** (jaise sirf \'Medium\' ya sirf \'Large\') ke pieces ko ek saath process kiya jata hai. \n* **Fayda:** Isse sorting aur bundling ke dauran mix-up hone ka risk khatam ho jata hai aur cutting floor par error-free production hoti hai.\n\n### 2. Smart Style Group / Production Mode\n* **Kahan use hota hai:** Factory Suite Pro ya advanced MES (Manufacturing Execution Systems) mein.\n* **Matlab:** Ek aisa operational mode jahan ek jaisi styling ya construction wale styles (styles with same SAM/operations) ko ek hi production line par club karke run kiya jata hai, taaki style changeover ka time (downtime) kam se kam ho.\n\n---\n\nBoss, kya aap yeh mode kisi specific software (jaise Factory Suite Pro, Gerber, Lectra, ya kisi specific sewing machine panel) ke context mein pooch rahe hain? Thoda detail denge toh aur exact bata dunga!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 11:55:25', 'text', NULL, NULL, 'sent', 0);
