INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065706958', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, garment manufacturing aur supply chain industry mein **OCR** ka matlab **\"Optical Character Recognition\"** hota hai. \n\nIsko simple terms mein samjhein toh yeh ek aisi technology hai jo **printed, handwritten, ya typed text ko digital text mein convert karti hai** taaki computer ya software usko padh aur samajh sake.\n\nApparel industry mein OCR ka use kahan aur kaise hota hai, aaiye dekhte hain:\n\n### 1. Fabric Roll Barcodes & Tags Read Karna\n* **Kaise hota hai:** Fabric rolls par jo mill tags ya batch numbers hote hain, unko manually type karne ke bajaye OCR technology ya scanners ki madad se turant scan karke ERP/MES system mein feed kar liya jata hai.\n* **Fayda:** Data entry ki galtiyan (human errors) nahi hoti aur time bachta hai.\n\n### 2. Cutting & Bundle Numbering\n* **Kaise hota hai:** Cutting room mein jab bundle tickets ya cut parts par numbering hoti hai, toh OCR systems ya smart devices se unhe easily track kiya jata hai ki kaun sa bundle kis size aur layer ka hai.\n\n### 3. Invoice aur Bill Processing (Accounts)\n* **Kaise hota hai:** Suppliers aur trims/accessories vendors ke invoices ko manually check karne ke bajaye OCR software automatic read karke quantity aur rates match kar leta hai.\n\n---\n\n**Factory Suite Pro ke perspective se:** \nJab aap cutting, inventory, ya shipping ke dauran koi paper slip ya tag scan karte hain, toh OCR background mein kaam karke usko digital data mein badalta hai taaki aapko har cheez live dashboard par dikh sake! \n\nBoss, kya aapko ise kisi specific process (jaise fabric scanning ya bill entry) mein use karne ke baare mein janna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 12:01:46', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792065721148', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, garment manufacturing mein **SAM** ka matlab **Standard Allowed Minute** (kai log ise **SMV** yaani Standard Minute Value bhi kehte hain) hota hai.\n\nIsko simple words mein samjhein toh: **\"Ek garment ya uska koi operation banane mein ek skilled operator ko standard conditions mein kitna time lagna chahiye.\"**\n\n---\n\n### 1. SAM Kyon Zaroori Hai? (Importance in Factory)\n* **Line Balancing:** Kis operator ko kya kaam dena hai aur line mein kitne machines lagengi, yeh decide karne ke liye.\n* **Production Target:** Ek din mein ek line kitne pieces banayegi (Capacity Planning), yeh SAM se hi nikalta hai.\n* **Costing & Pricing:** Buyer ko garment ka rate kya dena hai, labor cost kitni aayegi, yeh SAM par depend karta hai.\n* **Efficiency Calculation:** Operator ya line ki actual performance kitni hai (Target vs Actual).\n\n---\n\n### 2. SAM Calculate Kaise Hota hai? (Formula & Steps)\nSAM nikalne ka standard formula yeh hai:\n\n$$\\text{SAM} = \\text{Basic Time} \\times (1 + \\text{Allowance \\%})$$\n\nJahan:\n1. **Cycle Time / Observed Time:** Stopwatch se operator ka kaam record kiya jata hai (usually 5-10 cycles ka average).\n2. **Rating Factor:** Operator ki speed check ki jati hai (agar operator normal se fast kaam kar raha hai toh rating 110% hogi, slow hai toh 90%).\n   $$\\text{Basic Time} = \\text{Average Observed Time} \\times \\left(\\frac{\\text{Rating}}{100}\\right)$$\n3. **Allowances (%):** Operator ke thakne (Fatigue), personal needs, aur machine ki choti-moti rukawaton ke liye time joda jata hai (aamtaur par 10% se 20% tak hota hai).\n\n---\n\n**Example:**\nMaan lijiye ek shirt ki collar attach karne ka Basic Time **0.80 minutes** hai aur factory allowance **15%** hai:\n$$\\text{SAM} = 0.80 \\times (1 + 0.15) = 0.80 \\times 1.15 = \\mathbf{0.92 \\text{ Minutes}}$$\n\nBoss, kya aapko kisi specific style ya operation ka SAM nikalne ka tarika janna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 12:02:01', 'text', NULL, NULL, 'sent', 0);
