INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792067556751', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Bien sûr ! Nous pouvons tout à fait parler en français. \n\nComment puis-je vous aider avec vos opérations d\'usine aujourd\'hui ? Que vous souhaitiez vérifier des lots de production, calculer la consommation de tissu, analyser le SAM/SMV d\'un style ou suivre les goulots d\'étranglement (coupe, couture, finition), je suis là pour vous aider. \n\nQu\'aimeriez-vous vérifier dans l\'usine en premier ?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 12:32:36', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792067592242', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Kem cho! Chhokas, abhi thi aapne Gujarati ma vaat karishu. \n\nFactory Suite Pro ma tame mari pase shu check karva mango chho? Tamara mate kai kai options available chhe:\n\n* **Production Lots & Status:** Cutting, Stitching, ke Packing stage ma koi lot no status check karvo hoy.\n* **Fabric Consumption:** Koi style mate fabric kitlu lagse tenu calculation.\n* **SAM / SMV Analysis:** Garment manufacturing nu Standard Allowed Minute check karvu.\n* **Quality & Bottlenecks:** Factory ma koi delay ya bottleneck che ke nahi te jovu.\n\nBatao ji, aaaje factory ma shu check kariye?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 12:33:12', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792067654434', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Kem cho! Tamare SAM (Standard Allowed Minute) report jovo chhe. \n\nGarment manufacturing ma SAM (SMV) ghano important chhe, kem ke aa na basis par efficiency, line balancing, aur production targeting નક્કી થાય chhe. \n\nAhiya SAM/SMV calculate karva ni standard method chhe:\n\n### **SAM (Standard Allowed Minute) Formula:**\n$$\\text{SAM} = \\text{Basic Time} + (\\text{Basic Time} \\times \\text{Allowance } \\%)$$\n\nJya:\n1. **Basic Time:** Cycle Time $\\times$ Performance Rating (Worker speed factor).\n2. **Allowance %:** Personal needs, fatigue, aur machine delays mate (general ahiya 10% thi 20% rakhvama aave chhe).\n\n---\n\n### **Factory Suite Pro - SAM Report Breakdown:**\nTamari factory ma specific style no SAM report jovo hoy, to tame mane **Style Name / Number** kaho. Hu tmane niche ni details api saku chhu:\n* **Operation-wise breakdown:** (Cutting, Stitching, Finishing na alag-alag minutes).\n* **Target per hour per operator:** $\\text{Target} = \\frac{60 \\text{ minutes}}{\\text{SAM}}$\n* **Line Manpower Requirement:** Total target sathe match karva ketla operators joiye.\n\nBatao ji, kai specific style no SAM report jovo chhe tamare?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 12:34:14', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792067672772', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Kem cho! Tamare SAM (Standard Allowed Minute / SMV) vishe ekdam high-end, advanced ane detailed explanation joiye chhe. Factory Suite Pro na Industrial Engineering (IE) standard mujab, aa rahi high-end breakdown:\n\n---\n\n### **1. Advanced Definition & Anatomy of SAM**\nSAM fatak-fatak calculate karva maate nathi hoto; aa ek scientific time study che je operator ki efficiency ane style ni complexity define kare chhe. \n\n$$\\mathbf{SAM = Normal Time + Allowances}$$\n\nJema 2 main components aave chhe:\n* **Normal Time (Basic Time):** $\\text{Observed Cycle Time} \\times \\text{Rating Factor (PR)}$\n  *(Jya Rating Factor 100% standard worker ne represent kare chhe. Jo worker fast hoy to PR > 100%, slow hoy to < 100%.)*\n* **Total Allowances (%):** Aama 3 categories samel hoy chhe:\n  1. **Personal Allowance:** (e.g., restroom, water break - usually 5%)\n  2. **Fatigue Allowance:** (e.g., physical strain, environment - 5% to 10%)\n  3. **Contingency Allowance:** (e.g., thread breakage, bobbin change - 2% to 5%)\n\n---\n\n### **2. Industrial Engineering (IE) Impact & Formulas**\nHigh-end manufacturing ma, SAM direct factory na KPI ane costing sathe connected hoy chhe:\n\n* **Hourly Target per Operator (Line Balancing):**\n  $$\\text{Target per Hour} = \\frac{60 \\text{ minutes}}{\\text{SAM}} \\times \\text{Efficiency } \\%$$\n  *(Je style no SAM vadhare, te no hourly target ochho hase.)*\n\n* **Manpower Calculation (Pcs / Shift):**\n  $$\\text{Required Operators} = \\frac{\\text{Total Planned Output}}{\\text{Available Time in Min} \\times \\text{Line Efficiency} / \\text{SAM}}$$\n\n* **Cost per Piece (Labor Costing):**\n  $$\\text{Direct Labor Cost} = \\text{SAM} \\times \\left( \\frac{\\text{Operator Cost per Minute}}{\\text{Efficiency } \\%} \\right)$$\n\n---\n\n### **3. Why High-End SAM Control is Critical (Bottleneck Analysis):**\n1. **Line Balancing:** Je operations na SAM ma vadhare gap hoy (e.g., Operation A = 0.5 min, Operation B = 1.8 min), tya **WIP (Work in Progress)** jam thase ane bottleneck create thase. Balancing mate SAM breakdown hovu anivarya che.\n2. **SMV Audit & Method Engineering:** Motion Study (THERBLIGS) vapri ne waste movements reduce karva thi SAM optimize thay chhe, jethi factory ni capacity bache che.\n\nBatao ji, Factory Suite Pro ma tame koi specific style mate aa **Advanced SAM breakdown, Operation Bulletin, ya Line balancing** check karva mango chho?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 12:34:32', 'text', NULL, NULL, 'sent', 0);
