INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792072614690', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello ji! Main ekdum badiya hoon, aap batao, sab theek-thaak? \n\nFactory Suite Pro ke live data ke mutabiq aapki factory ki production par poori nazar rakhi hui hai. Bataiye, SS ke pending/uncut lots ki poori list chahiye ya kisi aur stage (Cutting, Stitching, Packing) ke baare mein janna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 13:56:54', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792072641654', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Bas sab badhiya! Factory ka kaam smoothly chal raha hai. \n\nLive data ke hisaab se, abhi hamare paas **SS** party ke total **331 lots** registered hain, jisme se **44 lots cutting ke liye pending** hain aur **287 lots** cut ho chuke hain.\n\nAapko kisi aur party (jaise koi aur buyer ya brand) ka status check karna hai, ya phir Stitching, Packing, ya kisi technical topic (jaise GSM calculation, Fabric consumption, ya SAM/SMV) ke baare mein kuch janna hai? Bataiye, kya help karun?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 13:57:21', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792072673116', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Garment manufacturing aur apparel industry mein career ke liye aapke paas bohot saare exciting aur high-growth options hain! Aapki interest aur skills ke hisaab se aap in fields mein se koi bhi choose kar sakte hain:\n\n### 1. **Industrial Engineering (IE) & Production Management**\n* **Kya karna hota hai:** Factory ki efficiency badhana, SAM/SMV calculate karna, line balancing karna, aur cost kam karna.\n* **Kyun karein:** Agar aapko numbers, data, aur process optimization pasand hai. Is field mein growth bohot fast hai (Industrial Engineer se Production Manager / Plant Head tak).\n\n### 2. **Merchandising & Supply Chain**\n* **Kya karna hota hai:** Buyer ke saath coordination karna, costing nikalna, fabric/trims ki sourcing karna aur order ko time par dispatch karana.\n* **Kyun karein:** Agar aapki communication acchi hai aur aapko management aur planning mein interest hai.\n\n### 3. **Quality Control (QC) & Quality Assurance (QA)**\n* **Kya karna hota hai:** Fabric checking, inline inspection, final audit aur DHU (Defect Hundred Units) ko control karna.\n* **Kyun karein:** Agar aapki nazar details par acchi hai aur aap standards maintain karne mein expert hain.\n\n### 4. **Garment Technology & CAD/CAM (Design & Pattern Making)**\n* **Kya karna hota hai:** Tech packs samajhna, patterns banana, grading karna, aur marker planning se fabric wastage kam karna.\n* **Kyun karein:** Agar aapka creative mind hai aur aapko garment construction ki technical knowledge pasand hai.\n\n---\n\n**Aapko kis cheez mein sabse zyada maza aata hai?** \n* Numbers, planning, aur factory floor management mein? *(Go for IE / Production)*\n* Buyers se baat karne aur orders handle karne mein? *(Go for Merchandising)*\n* Quality aur standards check karne mein? *(Go for QA)*\n\nBataiye, aapka current background ya interest kis taraf hai, phir main aapko ek proper step-by-step career roadmap bata deta hoon!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-15 13:57:53', 'text', NULL, NULL, 'sent', 0);
