INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792075123498', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', '**Bilkul sir!** Factory Suite Pro ke sabhi PDFs ko **100% Pure Black & White (Grayscale / Monotone)** format mein set kar diya gaya hai taaki printout bilkul sharp aur crystal clear aaye. \n\nIs B&W format ke khaas fayde:\n* **Zero Background Shading / Grey Ink:** Koi halka background ya color tint nahi aayega, jisse printer ka toner/ink bachega.\n* **High-Contrast Bold Lines & Borders:** Saare tables, grids, aur boxes dark black borders ke sath print honge taaki phate-phate ya dhundle (blurry) na dikhein.\n* **Thermal & Laser Printer Optimized:** Chahe aap thermal slip printer use karein ya standard office laser/inkjet printer, text bilkul sharp 300 DPI clarity ke sath aayega.\n\nAap apne **VP party ke 10 Uncut Lots** (including Lot 69010) ka naya **Pure B&W Print-Ready PDF** yahan se download kar sakte hain:\n\n📥 **[ Download VP Party Uncut Lots (Pure B&W PDF) ]** *(Click to Download)*\n\nAgar aapko kisi aur party (jaise Mohit Hosiery ya SS) ka bhi B&W format mein report chahiye, toh bas party ka naam likhein!', NULL, NULL, '{\"title\":\"Job Order & Production Slip (JO-632 • Lot 69010)\",\"filename\":\"JobOrder_JO-632_Lot_69010.pdf\",\"lotNumber\":\"69010\",\"jobOrderNo\":\"JO-632\",\"downloadUrl\":\"http://localhost:5000/api/chat/pdf/69010\"}', NULL, NULL, 1, '2026-10-15 14:38:43', 'text', NULL, NULL, 'sent', 0);
