INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792239113189', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, yeh error ka matlab bohot simple hai! \n\nAapka Node.js backend server (`server.js`) start nahi ho paa raha kyunki **`db.js`** file ek aisi file ko import kar rahi hai jo wahan exist nahi karti:\n👉 **`config/cloudinary.js`**\n\n### Iska Reason kya ho sakta hai?\n1. Ya toh `config/cloudinary.js` file aapne delete kar di ya galti se kisi aur folder mein move ho gayi.\n2. Ya fir aapne kisi aur branch/system se code pull kiya hai aur woh file missing hai.\n3. Agar aapne ES Modules (`import`/`export`) use kiye hain, toh yaad rakhein ki file path ke aage extension (.js) lagana zaroori hota hai kai baar, ya phir file wahan hai hi nahi.\n\n### Isko Fix Kaise Karein?\n1. Check karein ki aapke project ke andar `config` folder ke andar `cloudinary.js` naam ki file bani hui hai ya nahi.\n2. Agar nahi bani hai, toh `config/cloudinary.jal` (ya `.js`) file create karein aur Cloudinary ka setup code wahan daalein.\n3. Agar file ka naam ya path alag hai, toh `db.js` ke andar import statement ka path theek karein. \n\nBataiye, kya Cloudinary config ka code likhna hai ya koi file check karwani hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-17 12:11:53', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792239585164', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Boss, error exactly wahi same repeat ho raha hai! \n\nAapka Node.js environment strictly **ES Modules** use kar raha hai, aur woh `accessories-backend\\db.js` file ke andar se **`config/cloudinary.js`** file ko dhoondh raha hai par woh mil nahi rahi hai. \n\nIsse fix karne ke liye yeh 2 simple steps follow kariye:\n\n### Step 1: Check karein ki file hai ya nahi\nApne project folder mein check karein:\n`C:\\Users\\mheng\\OneDrive\\Desktop\\NEW ACCESSORY\\accessories-backend\\`\nKya iske andar **`config`** naam ka folder hai? Aur kya uske andar **`cloudinary.js`** file maujood hai?\n\n### Step 2: Agar file nahi hai, toh bana lijiye!\nAgar file missing hai, toh `config` folder ke andar `cloudinary.js` naam se ek file banayein aur usme yeh standard Cloudinary setup daal dein (agar aap Cloudinary use kar rahe hain):\n\n```javascript\nimport { v2 as cloudinary } from \'cloudinary\';\n\ncloudinary.config({\n  cloud_name: process.env.CLOUDINARY_CLOUD_NAME,\n  api_key: process.env.CLOUDINARY_API_KEY,\n  api_secret: process.env.CLOUDINARY_API_SECRET\n});\n\nexport default cloudinary;\n```\n\n### Step 3: Agar Cloudinary use nahi karna, toh `db.js` se hata dein\nAgar aapko is project mein Cloudinary ki zaroorat hi nahi hai, toh `db.js` file ko kholein, wahan jahan par `cloudinary.js` ko import kiya gaya hai (jaise `import ... from \'./config/cloudinary.js\'`), us line ko **delete ya comment out** kar dein.\n\nJaise hi aap yeh karenge, aapka server bina kisi error ke turant run ho jayega! Bataiye, kaunsa tarika try karna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-17 12:19:45', 'text', NULL, NULL, 'sent', 0);
