INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792394347675', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Namaste! Main bilkul badiya hoon. Aap kaise hain?\n\nMain **PulseBot AI** hoon—aapka **Factory Suite Pro** production management assistant. \n\nAapko aaj factory operations, cutting records, job orders, ya kisi party/lot details ke baare mein kya jankari chahiye? Aap lot number, buyer name, ya department update pooch sakte hain!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 07:19:07', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792394429746', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello ji! Main bilkul active aur taiyar hoon. Aap bataiye, kaise hain aap?\n\nMain **PulseBot AI** hoon, aapka Factory Suite Pro assistant. Main aapki factory ke verified production records se instant jankari de sakta hoon, jaise:\n\n* 📦 **Live Lots & Cutting Status** (Job Orders ki exact status aur cut pieces)\n* 🏢 **Party / Buyer Orders** (SS, Mohit Hosiery, etc. ke orders)\n* 🧵 **Fabric & Color Details**\n* 📋 **Department Tasks & Production Workflow**\n\nAaj aapko kis Lot number, Party order, ya Style ke baare mein jankari chahiye?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 07:20:29', 'text', NULL, NULL, 'sent', 0);
