INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792409480458', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello ji! Namaste! Kaise hain aap? 😊\n\nMain hoon **PulseBot AI**, aapka Factory Suite Pro assistant. Main aapki factory ki production details, live lots, cutting status, party orders (jaise SS, Mohit Hosiery), aur fabric consumption se judi har jaankari mein madad kar sakta hoon.\n\nBataiye, aaj main aapke liye kya kar sakta hoon? Koi specific order ya task check karna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 11:31:20', 'text', NULL, NULL, 'sent', 0);
