INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792411069462', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', '### 🔍 Visual Search: Design Comparison Results\n\nHumne aapki uploaded photo ko factory database ke registered design artworks se compare kiya.\n* 👕 **Detected Garment:** **Track Pants / Joggers** (The image shows four pairs of track pants in different colors with a hangtag attached to one, but no production lot number or manufacturing slip is visible.)\n* 📝 **Visual Analysis:** *None of the candidate artworks match the uploaded garment design. The uploaded photo shows a specific jogger style with a distinct diagonal panel seam across the thigh and knee area, which is not present in any of the provided candidate lots.*\n\n---\n\n### 🏭 All Similar Candidate Design Artworks in Factory Database (6 Designs):\n\n**1. Lot #61290** (Party: **SS** | Style: **REGULAR** | Fabric: **MH FLEECE**)\n\n![Lot 61290](http://localhost:5000/api/chat/image-proxy?id=1f7S5rDca96cnYeYsjzQG4ahoXx6HCHW0)\n\n**2. Lot #67044** (Party: **DB** | Style: **REGULAR** | Fabric: **MH FLEECE**)\n\n![Lot 67044](http://localhost:5000/api/chat/image-proxy?id=11fLCntkWIjmF-Zgp5xYAvEiKA1YSPf9W)\n\n**3. Lot #11955** (Party: **Mohit Hosiery** | Style: **JOGGER LOWER** | Fabric: **COTTON WAFLE BACK SIDE ANTIPILLING**)\n\n![Lot 11955](http://localhost:5000/api/chat/image-proxy?id=1OUvY6W6E6L04h9cnSjVRoMO910-BBYXV)\n\n**4. Lot #61233** (Party: **SS** | Style: **REGULAR** | Fabric: **UK LYCRA**)\n\n![Lot 61233](http://localhost:5000/api/chat/image-proxy?id=1gOTNpb3aazzGFwXHSSpaIHv9OqT3gWpW)\n\n**5. Lot #11974** (Party: **Mohit Hosiery** | Style: **JOGGER LOWER** | Fabric: **FANCY CLOTH MICKEY TT**)\n\n![Lot 11974](http://localhost:5000/api/chat/image-proxy?id=1luk-9A_6EcQwy6mtuN7BVIEjGqZBcxm7)\n\n**6. Lot #61256** (Party: **SS** | Style: **BOOT CUT** | Fabric: **UK LYCRA**)\n\n![Lot 61256](http://localhost:5000/api/chat/image-proxy?id=1OWtcZLaJmwsUg4fHLxzAfQ8JHcMW4-tB)\n\n💡 **Lot Verify Karne Ke Liye:**\nAgar aapka article inme se kisi design se match karta hai toh aap uska Lot Number bata sakte hain, ya phir is article ke **Cutting Slip** ya **Bundle Ticket** ki photo upload karein!', NULL, NULL, '{\"imageGallery\":[{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=1f7S5rDca96cnYeYsjzQG4ahoXx6HCHW0\",\"isCut\":false,\"party\":\"SS\",\"style\":\"REGULAR\",\"title\":\"Lot #61290 - SS (REGULAR)\",\"fabric\":\"MH FLEECE\",\"shades\":\"BLACK [4], BLACK [4], 15% [4], LT. GREY [4], LT. BEIGE [4], NAVY [4], OLIVE 4451 [4]\",\"garment\":\"LOWER\",\"jobOrder\":\"JO-1580\",\"lotNumber\":\"61290\"},{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=11fLCntkWIjmF-Zgp5xYAvEiKA1YSPf9W\",\"isCut\":false,\"party\":\"DB\",\"style\":\"REGULAR\",\"title\":\"Lot #67044 - DB (REGULAR)\",\"fabric\":\"MH FLEECE\",\"shades\":\"OFF WHITE (SURF) [2], NAVY (LT. BEIGE) [2], BLACK (OFF WHITE) [2], BLACK (OLIVE) [2], LT. GREY (BLACK) [2]\",\"garment\":\"TS - LOWER\",\"jobOrder\":\"JO-1556\",\"lotNumber\":\"67044\"},{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=1OUvY6W6E6L04h9cnSjVRoMO910-BBYXV\",\"isCut\":false,\"party\":\"Mohit Hosiery\",\"style\":\"JOGGER LOWER\",\"title\":\"Lot #11955 - Mohit Hosiery (JOGGER LOWER)\",\"fabric\":\"COTTON WAFLE BACK SIDE ANTIPILLING\",\"shades\":\"BLACK [4], BLACK [4], OFF WHITE [4], GREY [4], NAVY [4], D GREY [4], WHITE [4]\",\"garment\":\"LOWER\",\"jobOrder\":\"JO-1711\",\"lotNumber\":\"11955\"},{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=1gOTNpb3aazzGFwXHSSpaIHv9OqT3gWpW\",\"isCut\":false,\"party\":\"SS\",\"style\":\"REGULAR\",\"title\":\"Lot #61233 - SS (REGULAR)\",\"fabric\":\"UK LYCRA\",\"shades\":\"BLACK [1], D. MOUSE [1], IVORY [1], GREY [1], NAVY [1]\",\"garment\":\"TS - LOWER\",\"jobOrder\":\"JO-1340\",\"lotNumber\":\"61233\"},{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=1luk-9A_6EcQwy6mtuN7BVIEjGqZBcxm7\",\"isCut\":false,\"party\":\"Mohit Hosiery\",\"style\":\"JOGGER LOWER\",\"title\":\"Lot #11974 - Mohit Hosiery (JOGGER LOWER)\",\"fabric\":\"FANCY CLOTH MICKEY TT\",\"shades\":\"BLACK (D.GRAY UK LYCRA) [3], OFF WHITE (COFFEE) [3], OLIVE (L.GREY) [3], GREY (D GREY N) [3], FAWN (BLACK) [3], DEEP NAVY (L.GREY) [3]\",\"garment\":\"JOGGER\",\"jobOrder\":\"JO-1736\",\"lotNumber\":\"11974\"},{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=1OWtcZLaJmwsUg4fHLxzAfQ8JHcMW4-tB\",\"isCut\":false,\"party\":\"SS\",\"style\":\"BOOT CUT\",\"title\":\"Lot #61256 - SS (BOOT CUT)\",\"fabric\":\"UK LYCRA\",\"shades\":\"BLACK [1], BLACK [1], NAVY [1], PISTA [1], SILVER(STONE) [1], BEIGE [1], GREY(2) [1]\",\"garment\":\"LOWER\",\"jobOrder\":\"JO-1419\",\"lotNumber\":\"61256\"}]}', NULL, NULL, 1, '2026-10-19 11:57:49', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412223365', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Aapka message padh kar bahut achha laga, aapka swagat hai! 😊\n\nMain PulseBot AI hoon, aapka Factory Suite Pro assistant. Main yahan aapki production, stitching pipeline, aur factory ke daily tasks mein madad karne ke liye hoon. \n\nAapne shayad galti se kuch aur type kar diya hai, par koi baat nahi! Agar aapko **SS, Mohit Hosiery** ya kisi aur party ke **live lots, cutting status, ya fabric details** ke baare mein kuch bhi puchna ho, toh bejhijhak batayein. Main aapki poori madad karunga! \n\nBataiye, aaj main aapke liye kya kar sakta hoon?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:17:03', 'text', NULL, NULL, 'sent', 0);
