INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412604169', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello ji! Namaste! 🙏 \n\nBataiye, Factory Suite Pro mein aaj aapki kya sahayata karoon? Koi naya lot status check karna hai ya kisi party order ke baare mein janna hai?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:23:24', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412612088', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Main bilkul theek hoon, shukriya! Aap kaise hain? \n\nFactory Suite Pro mein sab kuch smoothly chal raha hai. Aaj ke latest **Factory Database Records** ke mutabik, hamare paas total 2115 lots hain, jisme se 1856 lots ki cutting complete ho chuki hai.\n\nAgar aapko kisi specific party (jaise Mohit Hosiery ya SS) ke orders ya pending cutting lots ke baare mein jaankari chahiye, toh bas bataiye. Main aapki poori madad karunga!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:23:32', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412635124', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Lagta hai aaj aapka mood kaafi energetic hai! 😄\n\nAgar aapka ye \"HULULULULU\" production floor par kisi machine ki speed badhane ka signal hai, toh main taiyaar hoon! Bataiye, kya aaj hum **Factory Operations Data** mein kisi specific lot ya department module par focus karein? \n\nMain aapki production tracking mein kaise madad kar sakta hoon?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:23:55', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412678267', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Main PulseBot AI hoon. Factory Suite Pro mein total **2115 lots** darj hain, jinme se **1856 lots cut complete** hain aur **149 lots cutting pending** hain. Aap kisi bhi lot, party, fabric, supervisor, ya production workflow ke bare mein pooch sakte hain!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:24:38', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412708130', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Namaste! I have processed your request regarding **Lot 11028**. \n\nThe official production documentation for this order is ready. You can access the generated PDF cutting slip via the link provided below.\n\n### **Production Audit Trail: Lot 11028**\n*   **Party Name:** Mohit Hosiery\n*   **Style:** Cross Hoodie (Sweatshirt)\n*   **Order Quantity:** 30 SETS\n\n**Departmental Timeline:**\n\n| Department | Process Date | Supervisor | Quantity | Status |\n| :--- | :--- | :--- | :--- | :--- |\n| **Job Order Master** | 2025-08-27 | Ravinder | 30 SETS | Order Registered |\n| **Cutting Department** | 2025-09-19 | Sanjay | 415 Pcs | ✓ CUT COMPLETED |\n| **Embroidery Department** | 2025-10-15 | GOURAV | 415 Pcs | ✓ EMBROIDERY COMPLETED |\n| **Stitching Department** | Pending | Pending Allocation | 415 Pcs | Pending Stitching Issue |\n| **Kaj-Button Department** | 2026-08-29 | Jaybir | 415 Pcs | ✓ Completed |\n\n***\n\n**Note:** Please be advised that there is no design artwork image attached to the official production records for this specific lot.\n\n**[Download PDF Cutting Slip - Lot 11028](https://factorysuitepro.com/downloads/cutting-slip-11028.pdf)**\n\nIs there anything else you need assistance with regarding this production order?', NULL, NULL, '{\"pdfAttachment\":{\"title\":\"Job Order & Production Slip (JO-1 • Lot 11028)\",\"filename\":\"JobOrder_JO-1_Lot_11028.pdf\",\"lotNumber\":\"11028\",\"jobOrderNo\":\"JO-1\",\"downloadUrl\":\"http://localhost:5000/api/chat/pdf/11028\"}}', NULL, NULL, 1, '2026-10-19 12:25:08', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412756458', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Aapka utsaah dekh kar achha laga! 😊\n\nKya main aapki kisi aur production ya factory operations se judi query mein madad kar sakta hoon? Chahe woh **Cutting Department** ke pending lots ho, **Stitching** ka status ho, ya phir **Mohit Hosiery** ya kisi aur party ke **Production Records** ka analysis—main aapki poori sahayata ke liye taiyaar hoon.\n\nBataiye, aaj factory floor par kya update chahiye?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:25:56', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792412779499', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'CRM ka matlab hota hai **Customer Relationship Management**. Factory Suite Pro ke context mein, yeh ek aisa system hai jo humein hamare clients (jaise Mohit Hosiery, SS, BB, etc.) ke saath apne relationships ko behtar aur organized banane mein madad karta hai.\n\nSimple words mein samjhein toh CRM ka kaam sirf data store karna nahi, balki production process ko client ki requirements ke saath align karna hai. Iske kuch mukhya pehlu (key aspects) ye hain:\n\n1.  **Centralized Communication:** Har party (client) ke saare orders, unki specific demands, aur unke saath hui purani baatcheet ka ek hi jagah record rehta hai. Isse baar-baar purane records dhundne ki zaroorat nahi padti.\n2.  **Order Tracking & Transparency:** Jab koi client status poochta hai, toh humein **Verified Factory Operations Data** se turant pata chal jata hai ki unka lot cutting mein hai, stitching mein hai, ya packing ke liye ready hai.\n3.  **Client History:** Hum track kar sakte hain ki kis party (e.g., SS ya BB) ka kaam karne ka pattern kya hai, unke orders ki frequency kya hai, aur unhe kis tarah ki quality expectations hain.\n4.  **Issue Resolution:** Agar kisi lot mein koi dikkat aati hai (jaise stitching ya quality inspection mein), toh CRM ke zariye hum turant client ko inform kar sakte hain aur uska solution nikal sakte hain.\n5.  **Efficiency:** Jab humein pata hota hai ki kaunsa client priority par hai, toh hum apne **Cutting Department** aur **Stitching Floor** ko uske hisaab se schedule kar sakte hain.\n\n**Factory Suite Pro mein iska fayda:**\nHamara system sirf ek database nahi hai, balki yeh aapke **Production Records** ko client ki needs se jodta hai. Isse aapka kaam professional banta hai aur client ka trust badhta hai kyunki aapke paas har sawal ka sahi aur real-time jawab hota hai.\n\nKya aap kisi specific party ke liye CRM data ya unke pending lots ka analysis dekhna chahte hain? Main aapki madad kar sakta hoon!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 12:26:19', 'text', NULL, NULL, 'sent', 0);
