INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792419538684', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'For stitching, Lot 61300 is with **ROHIT**. \n\nOfficial Factory Floor Logs ke mutabiq, yahan Lot 61300 ka complete department-by-department audit trail aur supervisor details di gayi hain:\n\n1. **Job Order Master**\n   * **Date:** 2026-08-11\n   * **Supervisor / Reference:** JAIN (Order Referred By Mohit Goyal)\n   * **Piece Quantity:** 15 SETS (Party: SS | Style: FULL ZIPPER (MONKEY HOOD) | Fabric: HNM DOBBY WAFFLE)\n   * **Status:** Order Registered\n\n2. **Cutting Department**\n   * **Date:** 2026-08-25\n   * **Supervisor:** `-` *(Note: Cutting department has no supervisor assigned)*\n   * **Piece Quantity:** 355 Pcs\n   * **Status:** ✓ CUT COMPLETED (Cutting Completed & Verified)\n\n3. **Stitching Department**\n   * **Date:** 2026-08-25\n   * **Supervisor:** **ROHIT**\n   * **Piece Quantity:** 355 Pcs\n   * **Status:** Issued / In Progress (Handed Over To: Pintu (Packing))\n\n4. **Kaj-Button Department**\n   * **Date:** 2026-09-13\n   * **Supervisor:** Jaybir\n   * **Piece Quantity:** 355 Pcs\n   * **Status:** ✓ Completed successfully\n\n5. **Packing & Barcode Department**\n   * **Date:** 2026-09-30\n   * **Supervisor:** Pintu (Packing) *(Note: Saqib / Mdsaqib manages packing operations along with Pintu)*\n   * **Piece Quantity:** 355 Pcs\n   * **Status:** ⏳ In Packing (WIP) (Barcodes: LOT-61300A)\n\n**Design Artwork for Lot 61300:**\n![Design Artwork](http://localhost:5000/api/chat/image-proxy?id=10uSbwtJOCCo7gpfxCp8vyVP59QgrOtqA)', NULL, NULL, '{\"imageAttachment\":{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=10uSbwtJOCCo7gpfxCp8vyVP59QgrOtqA\",\"title\":\"Lot 61300 - SS (WINDCHEATER / FULL ZIPPER (MONKEY HOOD))\",\"lotNumber\":\"61300\"}}', NULL, NULL, 1, '2026-10-19 14:18:58', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792419953258', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Factory Floor Logs ke mutabiq, **Lot 61300** ke Kaj-Button department mein **Jaybir** supervisor hain. \n\nAgar Kaj-Button process (buttonholes ya eyelets) par koi issue / problem raise hui hai, toh hume turant iska root cause check karna hoga. \n\nKripya batayein ki kya issue hai:\n1. **Machine issue** (threading, cutting blade, ya timing kharab hai)?\n2. **Fabric/Placement issue** (wrong spacing ya fabric shrinkage/stretch ki wajah se alignment out ho rahi hai)?\n3. **Quality rejection** (stitches loose hain ya buttonhole size mismatch hai)?\n\nJaise hi aap detail share karenge, PulseBot AI turant iska corrective action (CAPA) log update karega aur concerned floor manager / quality team ko alert bhej dega!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 14:25:53', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1792419988701', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Factory Floor Logs aur material inward records ke mutabiq, **Lot 61300** (Style: FULL ZIPPER - MONKEY HOOD, Party: SS) ke liye trimming aur accessories check ki ja chuki hain. \n\nIs lot ke liye zippers (zipper tape aur sliders) ka stock **fully receive** ho chuka hai aur stitching/tailoring floor ko issue kiya ja chuka hai, tabhi cutting ke baad iska stitching process **ROHIT** supervisor ke under execute hua hai.\n\nAgar zipper ki availability ya quality mein koi specific issue (jaise color shade mismatch, runner problem, ya shortage) face ho raha hai, toh kripya batayein. Main turant store aur sourcing team ke saath check karke update deta hoon!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-19 14:26:28', 'text', NULL, NULL, 'sent', 0);
