INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1793195174653', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! 👋 Main PulseBot AI hoon, aapka garment manufacturing assistant Factory Suite Pro se.\n\nMain aapki in sabhi cheezon mein help kar sakta hoon:\n* 📊 **Live Lots aur Audit History:** Kisi bhi lot ka current status ya photo/timeline.\n* ✂️ **Cutting Status:** Production records se verified accurate cutting aur process updates.\n* 🏢 **Party Orders:** SS, Mohit Hosiery, etc. ke orders aur details.\n* 🧵 **Fabrics & Tasks:** Fabric tracking aur pending factory tasks.\n\nBataiye, aaj main aapki kya madad karoon?', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-28 13:46:14', 'text', NULL, NULL, 'sent', 0);
INSERT INTO `chat_messages` (`id`, `channel_id`, `sender_id`, `sender_name`, `sender_role`, `sender_avatar`, `text`, `image_url`, `audio_url`, `file_attachment`, `reactions`, `task_attachment`, `is_ai`, `created_at`, `message_type`, `task_id`, `reply_to_message_id`, `status`, `is_deleted`) VALUES ('msg-ai-1793195248732', 'chan-ai', 'pulse-bot', 'PulseBot AI (Gemini)', 'AI Assistant', '🤖', 'Hello! Haanji, bataiye. 😊\n\nMain PulseBot AI hoon. Aapko kisi live lot, cutting status, party order (jaise Mohit Hosiery, SS), fabric tracking ya task ke baare mein koi jaankari chahiye? \n\nAap apna sawal pooch sakte hain!', NULL, NULL, NULL, NULL, NULL, 1, '2026-10-28 13:47:28', 'text', NULL, NULL, 'sent', 0);
