true,\"latestWipRemarks\":\"Elastic working pending\"},{\"pcs\":\"260 Pcs\",\"date\":\"2026-08-20\",\"dept\":\"Packing & Barcode Department\",\"notes\":\"Barcodes: LOT-61200A\",\"status\":\"✓ Packed (Barcode: LOT-61200A)\",\"stageName\":\"Packing & Dispatch\",\"supervisor\":\"Chavinath\",\"isCompleted\":true}],\"garment\":\"LOWER\",\"lotNumber\":\"61200\",\"jobOrderNo\":\"JO-1179\",\"isCancelled\":false,\"cancelReason\":\"\",\"currentStage\":\"Production Completed\",\"designImageUrl\":\"http://localhost:5000/api/chat/image-proxy?id=1Gxw1LZt_BYLGoGLL_Geo2q-BdOHnW5Tw\",\"latestWipRemark\":null,\"overallProgress\":100,\"latestWipTimestamp\":null,\"isStitchingComplete\":true,\"stitchingSupervisor\":\"MONU\"},\"imageAttachment\":{\"url\":\"http://localhost:5000/api/chat/image-proxy?id=1Gxw1LZt_BYLGoGLL_Geo2q-BdOHnW5Tw\",\"title\":\"Lot 61200 - SS (LOWER / BOXY FIT)\",\"lotNumber\":\"61200\"}}', NULL, NULL, 1, '2026-10-28 14:15:16', 'text', NULL, NULL, 'sent', 0);
